<?php $valor = static fn ($c, $p = '') => is_scalar($valores[$c] ?? null) ? (string) $valores[$c] : $p; ?>
<div class="flex max-w-4xl flex-col gap-4 pt-2 pb-8"><h1 class="font-display text-heading-xl text-text"><?= e('Endereço e deslocamento · Atendimento #' . $os->idOs) ?></h1><p class="text-body-md text-muted">Registre o local, a distância estimada e a regra combinada. A taxa cobrada deve constar como serviço no orçamento; estes campos não alteram preços nem pagamentos.</p>
<form method="post" action="<?= e(site_url('deslocamentos/formulario/' . $os->idOs)) ?>" class="grid gap-4 rounded-xl border border-border bg-surface p-4" novalidate <?= js_module('formulario/padrao') ?>><input type="hidden" name="<?= e($this->security->get_csrf_token_name()) ?>" value="<?= e($this->security->get_csrf_hash()) ?>">
<?= component('textarea', ['name' => 'endereco_atendimento', 'label' => 'Endereço do atendimento', 'value' => $valor('endereco_atendimento'), 'error' => $erros['endereco_atendimento'] ?? null, 'attrs' => ['maxlength' => 500]]) ?>
<?= component('input', ['name' => 'distancia_km', 'label' => 'Distância estimada (km)', 'value' => $valor('distancia_km', '0'), 'error' => $erros['distancia_km'] ?? null]) ?>
<?= component('input', ['name' => 'deslocamento_min', 'label' => 'Tempo de viagem antes do atendimento (min)', 'type' => 'number', 'value' => $valor('deslocamento_min', '0'), 'error' => $erros['deslocamento_min'] ?? null, 'attrs' => ['min' => 0, 'max' => 720, 'step' => 1], 'help' => 'Será sugerido para novos horários. Confira os intervalos na agenda.']) ?>
<?= component('textarea', ['name' => 'regra_deslocamento', 'label' => 'Regra de cobrança combinada', 'value' => $valor('regra_deslocamento'), 'error' => $erros['regra_deslocamento'] ?? null, 'attrs' => ['maxlength' => 500], 'help' => 'Ex.: taxa de R$ 30 para este endereço; ou R$ 2 por km acima de 10 km.']) ?>
<div><?= component('button', ['label' => 'Salvar logística', 'type' => 'submit']) ?><?= component('button', ['label' => 'Voltar', 'variant' => 'ghost', 'href' => site_url('os/visualizar/' . $os->idOs)]) ?></div></form></div>
